                $display("Mismatch for y=%b, w=%b: Y1 got %b, expected %b", y, w, Y1, exp_Y1);
                errors = errors + 1;
            end
            if (Y3 !== exp_Y3) begin
                $display("Mismatch for y=%b, w=%b: Y3 got %b, expected %b", y, w, Y3, exp_Y3);
                errors = errors + 1;
            end
