        // - In F and w=1 -> y[5] & w
        // (So Y3 = w & (y[1] | y[2] | y[3] | y[4] | y[5]))

        // Test vectors: Exhaustive combinations of states and w

        // State A (7'b0000001)
        check_outputs(7'b0000001, 1'b0, 1'b1, 1'b0); // w=0 -> goes to B (Y1=1)
        check_outputs(7'b0000001, 1'b1, 1'b0, 1'b0); // w=1 -> goes to A

