        check_outputs(7'b0001000, 1'b0, 1'b0, 1'b0); // w=0 -> goes to F
        check_outputs(7'b0001000, 1'b1, 1'b0, 1'b1); // w=1 -> goes to D (Y3=1)

        // State E (7'b0010000)
        check_outputs(7'b0010000, 1'b0, 1'b0, 1'b0); // w=0 -> goes to E
        check_outputs(7'b0010000, 1'b1, 1'b0, 1'b1); // w=1 -> goes to D (Y3=1)

        // State F (7'b0100000)
        check_outputs(7'b0100000, 1'b0, 1'b0, 1'b0); // w=0 -> goes to C
        check_outputs(7'b0100000, 1'b1, 1'b0, 1'b1); // w=1 -> goes to D (Y3=1)

        // Edge case: Unused/invalid one-hot states (e.g. all zeros or multiple bits)
        check_outputs(7'b0000000, 1'b0, 1'b0, 1'b0);
        check_outputs(7'b1111111, 1'b1, 1'b0, 1'b1);

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
